
.ghost-root {
  font-family: var(--font-tomb);
  width: 100%;
  max-width: 720px;
  margin: 0 auto;
  background: linear-gradient(180deg, #0d1417, #101d22);
  border: 1px solid var(--c-water);
  border-radius: 10px;
  color: var(--c-flesh);
  font-size: 13px;
  line-height: 1.45;
  box-shadow: 0 2px 14px rgba(0, 0, 0, 0.55), inset 0 0 30px rgba(46, 95, 122, 0.07);
  position: relative;
  overflow: hidden;

  &::before {
    content: '';
    position: absolute;
    inset: 0;
    pointer-events: none;
    opacity: 0.3;
    background-image:
      radial-gradient(ellipse at 18% 8%, rgba(46, 95, 122, 0.22), transparent 45%),
      radial-gradient(ellipse at 82% 92%, rgba(74, 125, 107, 0.13), transparent 40%),
      radial-gradient(ellipse at 55% 45%, rgba(142, 42, 42, 0.07), transparent 50%);
  }
}

.ghost-title {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 8px 12px;
  cursor: pointer;
  user-select: none;
  border-bottom: 1px solid var(--c-line);
  position: relative;
}

.ghost-ic {
  color: var(--c-water);
  font-size: 1.05rem;
  animation: ghostFloat 3s ease-in-out infinite;
}

.ghost-name {
  font-size: 1.1rem;
  font-weight: bold;
  letter-spacing: 0.08em;
}

.ghost-time {
  font-size: 1rem;
}

.ghost-core {
  flex: 1;
  display: flex;
  flex-direction: column;
  gap: 3px;
  min-width: 120px;
}

.ghost-gauge {
  height: 7px;
  border-radius: 4px;
  background: rgba(122, 139, 148, 0.18);
  overflow: hidden;
  border: 1px solid rgba(122, 139, 148, 0.22);

  i {
    display: block;
    height: 100%;
    border-radius: 3px;
    transition: width 0.6s ease;
  }
}

.g-grime i {
  background: linear-gradient(90deg, #5a1b1b, var(--c-grime));
}

.g-fade i {
  background: linear-gradient(90deg, var(--c-fade), #c3ccd1);
}

.ghost-chev {
  color: var(--c-mist);
  font-size: 0.75rem;
  transition: transform 0.3s ease;
}

.ghost-body {
  padding: 10px 12px;
  position: relative;
}

.ghost-root:not(.open) .ghost-body {
  display: none;
}

.ghost-root.open .ghost-chev {
  transform: rotate(180deg);
}

/* 情境覆盖：沉底（怨气≥80 或 记忆≤20） */
.ghost-root.drowned {
  .ghost-title {
    background: rgba(142, 42, 42, 0.12);
  }
  .ghost-name {
    color: var(--c-grime);
    text-shadow: 0 0 8px rgba(142, 42, 42, 0.5);
  }
  &::before {
    opacity: 0.5;
  }
  .ghost-body {
    background: rgba(142, 42, 42, 0.05);
  }
}

/* 白天警告 */
.ghost-root.daylight {
  .ghost-time {
    color: #c9a227;
    text-shadow: 0 0 6px rgba(201, 162, 39, 0.6);
  }
  .ghost-title {
    border-bottom-color: rgba(201, 162, 39, 0.4);
  }
}

@keyframes ghostFloat {
  0%,
  100% {
    transform: translateY(0);
    opacity: 0.7;
  }
  50% {
    transform: translateY(-2px);
    opacity: 1;
  }
}
